def I8.Insts.TinysetSet64Fits64.from_u64 (x : Std.U64) : RustM Std.I8 := do
  let i ← x >>> 1#i32
  let abs ← lift (UScalar.hcast .I8 i)
  let i1 ← lift (x &&& 1#u64)
  let neg ← lift (UScalar.hcast .I8 i1)
  let i2 ← neg * (-2)#i8
  let i3 ← i2 + 1#i8
  abs * i3

